// Simple Asteroid Dodge game targeting <canvas id="game"></canvas>
// Ship moves horizontally at bottom, asteroids fall and increase speed.

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth || 800;
canvas.height = canvas.clientHeight || 600;

// Ship definition
const ship = {
  width: 40,
  height: 20,
  x: canvas.width / 2 - 20,
  y: canvas.height - 30,
  speed: 5,
  moveLeft: false,
  moveRight: false,
  draw() {
    ctx.fillStyle = '#0f0';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  },
  update() {
    if (this.moveLeft) this.x = Math.max(0, this.x - this.speed);
    if (this.moveRight) this.x = Math.min(canvas.width - this.width, this.x + this.speed);
  }
};

// Asteroid pool
let asteroids = [];
let spawnTimer = 0;
let spawnInterval = 90; // frames
let speedFactor = 1;
let gameOver = false;
let score = 0;

function spawnAsteroid() {
  const size = Math.random() * 30 + 20;
  asteroids.push({
    x: Math.random() * (canvas.width - size),
    y: -size,
    size,
    speed: 2 * speedFactor + Math.random() * 2
  });
}

function updateAsteroids() {
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.y += a.speed;
    // remove if off screen
    if (a.y > canvas.height) {
      asteroids.splice(i, 1);
      score++;
      // gradually increase difficulty
      if (score % 10 === 0) speedFactor += 0.2;
    } else if (collision(a, ship)) {
      gameOver = true;
    }
  }
}

function drawAsteroids() {
  ctx.fillStyle = '#888';
  for (const a of asteroids) {
    ctx.beginPath();
    ctx.arc(a.x + a.size / 2, a.y + a.size / 2, a.size / 2, 0, Math.PI * 2);
    ctx.fill();
  }
}

function collision(ast, shp) {
  return (
    ast.x < shp.x + shp.width &&
    ast.x + ast.size > shp.x &&
    ast.y < shp.y + shp.height &&
    ast.y + ast.size > shp.y
  );
}

function drawScore() {
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + score, 10, 20);
}

function gameLoop() {
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#f00';
    ctx.font = '30px sans-serif';
    ctx.fillText('Game Over', canvas.width / 2 - 80, canvas.height / 2);
    ctx.fillStyle = '#fff';
    ctx.font = '20px sans-serif';
    ctx.fillText('Score: ' + score, canvas.width / 2 - 50, canvas.height / 2 + 30);
    return;
  }

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ship.update();
  ship.draw();

  if (spawnTimer++ >= spawnInterval) {
    spawnAsteroid();
    spawnTimer = 0;
    // slightly speed up spawns
    if (spawnInterval > 30) spawnInterval -= 0.5;
  }

  updateAsteroids();
  drawAsteroids();
  drawScore();

  requestAnimationFrame(gameLoop);
}

// Input handling
window.addEventListener('keydown', e => {
  if (e.key === 'ArrowLeft') ship.moveLeft = true;
  if (e.key === 'ArrowRight') ship.moveRight = true;
});
window.addEventListener('keyup', e => {
  if (e.key === 'ArrowLeft') ship.moveLeft = false;
  if (e.key === 'ArrowRight') ship.moveRight = false;
});

// Start game
requestAnimationFrame(gameLoop);
